using RegistrationService.Entities;using Microsoft.EntityFrameworkCore;namespace RegistrationService.Data;public sealed class RegistrationDbContext(DbContextOptions<RegistrationDbContext> options):DbContext(options){public DbSet<ExamRegistration> Registrations=>Set<ExamRegistration>();protected override void OnModelCreating(ModelBuilder b){b.Entity<ExamRegistration>().HasIndex(x=>new{x.CandidateNumber,x.ExamSession}).IsUnique();b.Entity<ExamRegistration>().Property(x=>x.CandidateNumber).HasMaxLength(40).IsRequired();b.Entity<ExamRegistration>().Property(x=>x.CandidateName).HasMaxLength(160).IsRequired();b.Entity<ExamRegistration>().Property(x=>x.ExamSession).HasMaxLength(40).IsRequired();b.Entity<ExamRegistration>().Property(x=>x.Subjects).HasMaxLength(500).IsRequired();}}